exercises.starter_code:
def expedition_report(party):
    total_health = 0
    needs_rest = False
    for member in party:
        total_health = member["health"]
        if member["health"] > 5:
            needs_rest = True
    return {"member_count": len(party), "total_health": total_health, "needs_rest": needs_rest}

exercises.reference_solution:
def expedition_report(party):
    total_health = 0
    needs_rest = False
    for member in party:
        total_health = total_health + member["health"]
        if member["health"] < 5:
            needs_rest = True
    return {"member_count": len(party), "total_health": total_health, "needs_rest": needs_rest}
